import click
import click.utils
import click.testing
import sys

@click.group()
def cli():
    pass

@cli.command()
@click.option('--count', default=1, help='Number of times to repeat the command')
@click.option('--name', default='default_name', help='Name to display')
def hello(count, name):
    """Print a message for a specified number of times"""
    for _ in range(count):
        click.echo(f"Hello, {name}!")

@cli.command()
@click.option('--count', default=1, help='Number of times to repeat the command')
@click.option('--name', default='default_name', help='Name to display')
def greet(count, name):
    """Print a personalized greeting message"""
    for _ in range(count):
        click.echo(f"Hello, {name}!")

def generate_man_pages():
    for command in ['hello', 'greet']:
        try:
            click.testing.run_command(f'man {command}')
        except click.MissingCommandError:
            print(f"Man page for command '{command}' not found.")

if __name__ == '__main__':
    cli()
    generate_man_pages()
