```python
import asyncio
import json
import websockets
import nbclient

class WebSocketProxy:
    def __init__(self, server_url, proxy_url):
        self.server_url = server_url
        self.proxy_url = proxy_url

    async def websocket_connect(self, websocket):
        try:
            await websocket.send(json.dumps({"type": "connect", "proxy_url": self.proxy_url}))
            return True
        except websockets.ConnectionClosed:
            return False

    async def websocket_send(self, websocket, data):
        try:
            await websocket.send(json.dumps(data))
            return True
        except websockets.ConnectionClosed:
            return False

    async def websocket_receive(self, websocket):
        try:
            while True:
                try:
                    data = await websocket.recv()
                    if data == "disconnect":
                        break
                except websockets.ConnectionClosed:
                    break
        except websockets.ConnectionClosed:
            pass

        try:
            if self.websocket_connect(websocket):
                data = json.loads(await websocket.recv())
                if data["type"] == "update":
                    await self.websocket_send(websocket, {"type": "update", "data": data})
                elif data["type"] == "disconnect":
                    await self.websocket_send(websocket, {"type": "disconnect"})
        except websockets.ConnectionClosed:
            pass

    async def websocket_handle(self, websocket):
        while True:
            try:
                data = await websocket.recv()
                if data == "disconnect":
                    break
            except websockets.ConnectionClosed:
                break

            try:
                if data["type"] == "update":
                    await self.websocket_send(websocket, {"type": "update", "data": data})
            except websockets.ConnectionClosed:
                break

async def main():
    server_url = "http://localhost:8888"
    proxy_url = "http://localhost:8888/proxy"

    async with websockets.serve(WebSocketProxy(server_url, proxy_url), "localhost", 8888):
        print("WebSocket proxy server listening on port 8888")
        await asyncio.Future()  # run forever

asyncio.get_event_loop().run_until_complete(main())
asyncio.get_event_loop().run_forever()
```

This code creates a WebSocket proxy server that allows multiple clients to connect to a Jupyter Notebook/Lab server and receive real-time updates in their preferred language. The proxy server uses a simple proxy URL to forward incoming messages from the Jupyter Notebook/Lab server to the client's preferred language.

