    return Session.query.all()

# Create a function to get a user by id
def get_user(id):
    return Session.query.get(id)

# Create a function to update a user
def update_user(id, new_data):
    user = get_user(id)
    if user:
        user.username = new_data['username']
        user.email = new_data['email']
        user.save()
        return user
    else:
        return None

# Create a function to delete a user
def delete_user(id):
    user = get_user(id)
    if user:
        user.delete()
        user.save()
        return user
    else:
        return None

# Create a function to create a new user
def create_user_new(username, email):
    return create_session(user_id=username)
