    query = f"CREATE TABLE IF NOT EXISTS {table_name} (id INT64 PRIMARY KEY, name TEXT)"
    try:
        client.execute(query)
        click.echo(f"Table {table_name} created successfully")
    except Exception as e:
        click.echo(f"Failed to create table {table_name}: {str(e)}")

# Insert data
def insert_data(client, data):
    table_name = "your_table_name"
    query = f"INSERT INTO {table_name} (name) VALUES (%s)"
    try:
        client.execute(query, data)
        click.echo(f"Data inserted into table {table_name} successfully")
    except Exception as e:
        click.echo(f"Failed to insert data into table {table_name}: {str(e)}")

# Read data
def read_data(client, query):
    table_name = "your_table_name"
    try:
        result = client.execute(query)
        data = result.fetchall()
        click.echo(f"Data from table {table_name}: {data}")
