import datetime
import threading
import queue
from typing import Dict, List

class Workflow:
    def __init__(self):
        self.tasks = {}
        self.current_task = None
        self.error_queue = queue.Queue()

    def add_task(self, task_name: str, task_description: str):
        """Add a task to the workflow"""
        self.tasks[task_name] = task_description
        if self.current_task:
            raise ValueError("Cannot add task to existing task")
        self.current_task = task_name

    def start_task(self, task_name: str):
        """Start a task in the workflow"""
        if task_name not in self.tasks:
            raise ValueError("Task not found")
        self.current_task = task_name

    def stop_task(self, task_name: str):
        """Stop a task in the workflow"""
        if task_name not in self.tasks:
            raise ValueError("Task not found")
        if self.current_task == task_name:
            raise ValueError("Cannot stop task you are currently running")
        self.current_task = None

    def track_job(self, job_id: str):
        """Track a job in the workflow"""
        if job_id not in self.tasks:
            raise ValueError("Job not found")
        self.error_queue.put(f"Job {job_id} failed")

    def run_job(self):
        """Run the next task in the workflow"""
        if not self.current_task:
            raise ValueError("No tasks available")
        task_name = self.tasks[self.current_task]
        try:
            self.start_task(task_name)
        except ValueError as e:
            print(e)
            return
        try:
            self.current_task = None
        except ValueError as e:
            print(e)
            return
        try:
            self.track_job(self.current_task)
        except ValueError as e:
            print(e)
            return


def main():
    workflow = Workflow()
    while True:
        print("Workflow Options:")
        print("1. Add task")
        print("2. Start task")
        print("3. Stop task")
        print("4. Track job")
        print("5. Run job")
        print("6. Quit")
        choice = input("Choose an option: ")
        if choice == "1":
            task_name = input("Enter task name: ")
            task_description = input("Enter task description: ")
            workflow.add_task(task_name, task_description)
        elif choice == "2":
            task_name = input("Enter task name: ")
            workflow.start_task(task_name)
        elif choice == "3":
            task_name = input("Enter task name: ")
            workflow.stop_task(task_name)
        elif choice == "4":
            job_id = input("Enter job ID: ")
            workflow.track_job(job_id)
        elif choice == "5":
            workflow.run_job()
        elif choice == "6":
            break
        else:
            print("Invalid option")

if __name__ == "__main__":
    main()
```

