import torch
import torch.nn as nn
import torch.nn.functional as F

class TokenMergeGraph(nn.Module):
    def __init__(self, num_tokens, embedding_dim):
        super(TokenMergeGraph, self).__init__()
        self.num_tokens = num_tokens
        self.embedding_dim = embedding_dim
        self.graph = self._build_graph()

    def _build_graph(self):
        graph = {}
        for i in range(self.num_tokens):
            graph[i] = []
            for j in range(i + 1, self.num_tokens):
                similarity = self._calculate_similarity(i, j)
                if similarity > 0.5:
                    graph[i].append(j)
        return graph

    def _calculate_similarity(self, token1, token2):
        # Simple cosine similarity function
        # Replace with actual cosine similarity calculation if needed
        return 0.5

    def merge_tokens(self, token1, token2):
        if token1 not in self.graph or token2 not in self.graph:
            return None

        # Find the closest neighbor for each token
        closest_neighbors = {}
        for neighbor in self.graph[token1]:
            closest_neighbors[neighbor] = self._calculate_similarity(token1, neighbor)

        # Merge tokens based on their similarity and proximity
        if closest_neighbors[token2] > 0.5:
            return token1, token2

        # Find the closest neighbor for the second token
        closest_neighbor = min(self.graph[token2], key=self._calculate_similarity)
        return token1, closest_neighbor

    def get_merge_history(self, token):
        if token not in self.graph:
            return None

        merge_history = []
        for neighbor in self.graph[token]:
            merge_history.append((neighbor, self._calculate_similarity(token, neighbor)))
        return merge_history

# Example usage:
