import jsonpath

class JsonPathParser:
    def __init__(self, json_str):
        self.json_str = json_str

    def parse(self):
        try:
            return jsonpath.parse(self.json_str)
        except jsonpath.JsonPathError as e:
            raise ValueError("Invalid JSONPath expression: {}".format(e))

    def evaluate(self, expression):
        try:
            return jsonpath.eval(self.json_str, expression)
        except jsonpath.JsonPathError as e:
            raise ValueError("Invalid JSONPath expression: {}".format(e))

class Node:
    def __init__(self, value):
        self.value = value

    def __repr__(self):
        return str(self.value)

class AST:
    def __init__(self):
        self.nodes = {}

    def add_node(self, node):
        self.nodes[node.value] = node

    def traverse(self, node, parent=None):
        if parent:
            for key, value in parent.items():
                if isinstance(value, Node):
                    yield from self.traverse(value, node)
        else:
            for key, value in node.items():
                yield from self.traverse(value, node)

    def to_dict(self):
        return {key: value.value for key, value in self.nodes.items()}

def jsonpath_parser(json_str):
    parser = JsonPathParser(json_str)
    ast = AST()
    ast.add_node(Node(parser.parse()))
    return ast

def jsonpath_eval(ast, expression):
    ast.add_node(Node(ast.to_dict()))
    return ast.evaluate(expression)

# Example usage
json_str = '''
{
    "name": "John",
    "age": 30,
    "address": {
        "street": "123 Main St",
        "city": "Anytown",
        "state": "CA",
        "zip": "12345"
    },
    "cars": ["Toyota", "Honda", "Ford"]
}
'''

parser = jsonpath_parser(json_str)
ast = jsonpath_parser.parse()
expression = "address.city"
result = jsonpath_eval(ast, expression)
print(result)
```

This code defines a `JsonPathParser` class that parses a JSONPath expression and returns an abstract syntax tree (AST) representation of the parsed expression. The `evaluate` method evaluates the AST expression and returns the result.

The `Node` class represents a JSON value or a binary expression, and the `AST` class represents the AST of the parsed expression.

The `jsonpath_parser` function creates a `JsonPathParser` instance and calls the `parse` method to parse the input JSON string. It then creates an `AST` instance and adds nodes to it using the `to_dict` method to convert the parsed expression into a dictionary.

The `jsonpath_eval` function evaluates the AST expression using the `evaluate` method and returns the result. In the example usage, we create a JSON string, parse it using `jsonpath_parser`, and evaluate the expression "address.city" using `jsonpath_eval`.

