import functools
import time
import random

def retry(max_attempts=3, callback=None):
    """
    A decorator that retries a function up to a specified maximum number of attempts
    before calling a callback function.

    Args:
        max_attempts (int, optional): The maximum number of attempts to make. Defaults to 3.
        callback (function, optional): The function to call when the maximum attempts are reached. Defaults to None.

    Returns:
        function: A decorated function that retries the original function up to the maximum number of attempts.
    """

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempts += 1
                    if attempts < max_attempts:
                        print(f"Attempt {attempts} failed with error: {e}")
                    else:
                        if callback:
                            callback(e)
                        else:
                            print(f"All attempts failed. Retrying...")
                        break
            else:
                if callback:
                    callback(e)
                else:
                    print("All attempts failed. Retrying...")
        return wrapper
    return decorator

# Example usage:
@retry(max_attempts=5)
def example_function():
    # Simulate an expensive operation
    time.sleep(random.uniform(0.1, 1.0))
    print("Function executed successfully")

example_function()
