import json
import requests
from requests.exceptions import ProxyError

class TM1Client:
    def __init__(self, server_url, username, password, client_id, client_secret):
        self.server_url = server_url
        self.username = username
        self.password = password
        self.client_id = client_id
        self.client_secret = client_secret

    def authenticate(self):
        auth_url = f"{self.server_url}/v1/login"
        headers = {"Content-Type": "application/json"}
        data = {
            "grant_type": "password",
            "username": self.username,
            "password": self.password,
            "client_id": self.client_id,
            "client_secret": self.client_secret
        }
        response = requests.post(auth_url, headers=headers, data=json.dumps(data))
        if response.status_code == 200:
            return True
        else:
            raise Exception(f"Authentication failed: {response.text}")

    def connect_to_tmi(self, cube_id):
        auth_url = f"{self.server_url}/v1/login"
        headers = {"Content-Type": "application/json"}
        data = {
            "grant_type": "client_credentials",
            "client_id": self.client_id,
            "client_secret": self.client_secret
        }
        response = requests.post(auth_url, headers=headers, data=json.dumps(data))
        if response.status_code == 200:
            token = response.json()["access_token"]
            headers["Authorization"] = f"Bearer {token}"
            return token
        else:
            raise Exception(f"Connection to TM1 failed: {response.text}")

    def get_tmi_connection(self, token):
        url = f"{self.server_url}/v1/tmi"
        headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception(f"Failed to get TM1 connection: {response.text}")

    def execute_calculation(self, calculation_name, parameters):
        cube_url = f"{self.server_url}/v1/cubes/{cube_id}/calculations"
        headers = {"Authorization": f"Bearer {self.get_tmi_connection(self.server_url)['access_token']}", "Content-Type": "application/json"}
        data = {
            "name": calculation_name,
            "parameters": parameters
        }
        response = requests.post(cube_url, headers=headers, data=json.dumps(data))
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception(f"Failed to execute calculation: {response.text}")

    def get_mdxdatasource(self, cube_id):
        url = f"{self.server_url}/v1/cubes/{cube_id}/mdxdatasources"
        headers = {"Authorization": f"Bearer {self.get_tmi_connection(self.server_url)['access_token']}", "Content-Type": "application/json"}
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception(f"Failed to get MDX data source: {response.text}")

    def get_calculation(self, cube_id, calculation_name):
        url = f"{self.server_url}/v1/cubes/{cube_id}/calculations/{calculation_name}"
        headers = {"Authorization": f"Bearer {self.get_tmi_connection(self.server_url)['access_token']}", "Content-Type": "application/json"}
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception(f"Failed to get calculation: {response.text}")

# Example usage
client = TM1Client("https://example.com/tm1", "username", "password", "client_id", "client_secret")
cube_id = "12345"
calculation_name = "My Calculation"
parameters = {"param1": "value1", "param2": "value2"}

