import json
import os

class TaskQueue:
    def __init__(self, config_file):
        self.config_file = config_file
        self._load_config()

    def _load_config(self):
        with open(self.config_file, 'r') as f:
            self._config = json.load(f)

    def _create_config_section(self, section_name):
        config_section = f" [{section_name}]"
        return config_section + "\n"

    def _create_task_section(self, task_section_name):
        task_section = f"  {task_section_name}\n"
        return task_section + "\n"

    def _create_worker_section(self, worker_section_name):
        worker_section = f"  {worker_section_name}\n"
        return worker_section + "\n"

    def _create_pools_section(self, pools_section):
        pools_section = f"  {pools_section}\n"
        return pools_section + "\n"

    def _load_config_sections(self):
        config_sections = self._config.get('task_queue', {}).get('config', {})
        return config_sections

    def _load_pools_config(self, pools_config):
        return pools_config.get('pools', {})

    def _load_workers_config(self, workers_config):
        return workers_config.get('workers', {})

    def _create_pools(self, pools_config):
        for pool_name, pool_config in pools_config.items():
            self._create_pools_section(f"{pool_name}_config")
            self._create_pools_section(f"{pool_name}_workers")

    def _create_workers(self, workers_config):
        for worker_name, worker_config in workers_config.items():
            self._create_worker_section(f"{worker_name}_config")
            self._create_worker_section(f"{worker_name}_pools")

    def _create_tasks(self, tasks_config):
        for task_name, task_config in tasks_config.items():
            self._create_task_section(f"{task_name}_config")

    def _load_tasks_config(self, tasks_config):
        return tasks_config.get('tasks', [])

    def _load_worker_configs(self, worker_configs):
        return self._load_pools_config(worker_configs)

    def _load_worker_configs_tasks(self, worker_configs_tasks):
        return self._load_tasks_config(worker_configs_tasks)

    def create_task_queue(self, task_name, worker_name, pool_name):
        if self._create_pools(self._load_worker_configs(self._load_worker_configs_tasks([{"task_name": task_name, "worker_name": worker_name, "pool_name": pool_name}]])):
            return True
        else:
            return False

    def start_task_queue(self):
        if self._load_tasks_config(self._load_worker_configs(self._load_worker_configs_tasks([{"task_name": task_name, "worker_name": worker_name, "pool_name": pool_name} for task_name, worker_name, pool_name in self._create_tasks(self._config['tasks'])]))):
            print("Task queue is running.")
        else:
            print("No tasks defined in the configuration.")

def main():
    config_file = 'task_queue_config.json'
    task_queue = TaskQueue(config_file)
    task_queue.start_task_queue()
    task_queue.create_task_queue('my_task', 'my_worker', 'my_pool')

if __name__ == '__main__':
    main()
```

