```python
import os
import time
from datetime import datetime

class ExperimentManager:
    def __init__(self):
        self.experiments = {}

    def create_experiment(self, name, description):
        experiment_id = len(self.experiments) + 1
        self.experiments[experiment_id] = {
            'name': name,
            'description': description,
            'status': 'pending'
        }
        return experiment_id

    def schedule_experiment(self, experiment_id):
        self.experiments[experiment_id]['status'] = 'scheduled'

    def track_progress(self, experiment_id):
        if experiment_id in self.experiments:
            self.experiments[experiment_id]['status'] = 'running'
            print(f"Experiment {self.experiments[experiment_id]['name']} is running.")
        else:
            print(f"Experiment {experiment_id} does not exist.")

    def store_result(self, experiment_id, result):
        if experiment_id in self.experiments:
            self.experiments[experiment_id]['result'] = result
            print(f"Experiment {self.experiments[experiment_id]['name']} has been stored with result {result}.")
        else:
            print(f"Experiment {experiment_id} does not exist.")

    def delete_experiment(self, experiment_id):
        if experiment_id in self.experiments:
            del self.experiments[experiment_id]
            print(f"Experiment {self.experiments[experiment_id]['name']} has been deleted.")
        else:
            print(f"Experiment {experiment_id} does not exist.")

experiment_manager = ExperimentManager()

while True:
    print("\n1. Create Experiment")
    print("2. Schedule Experiment")
    print("3. Track Progress")
    print("4. Store Result")
    print("5. Delete Experiment")
    print("6. Quit")
    choice = input("Choose an option: ")

    if choice == "1":
        name = input("Enter experiment name: ")
        description = input("Enter experiment description: ")
        experiment_id = experiment_manager.create_experiment(name, description)
        print(f"Experiment {name} created with ID {experiment_id}.")
    elif choice == "2":
        experiment_id = input("Enter experiment ID: ")
        experiment_manager.schedule_experiment(experiment_id)
