import os
import git
import subprocess

class ModelVersionControl:
    def __init__(self, model_path):
        self.model_path = model_path

    def create_repo(self):
        repo_name = f"model_{datetime.now().strftime('%Y%m%d%H%M%S')}"
        os.mkdir(f"{repo_name}/")
        subprocess.run(f"git init {repo_name}/")
        subprocess.run(f"git clone https://{repo_name}/ {repo_name}/")
        return repo_name

    def add_file(self, file_path):
        repo_path = f"{self.model_path}/{file_path}"
        subprocess.run(f"git add {repo_path}")
        subprocess.run(f"git commit -m \"Add {file_path}\"")

    def commit_changes(self):
        repo_path = f"{self.model_path}/{os.listdir(self.model_path)[-1]}"
        subprocess.run(f"git commit -m \"Commit changes\"")

    def push_repo(self):
        repo_path = f"{self.model_path}/{os.listdir(self.model_path)[-1]}"
        subprocess.run(f"git push -u origin master")

model_version_control = ModelVersionControl("path/to/model")

while True:
    print("\n1. Create Repository")
    print("2. Add File")
    print("3. Commit Changes")
    print("4. Push Repository")
    print("5. Quit")
    choice = input("Choose an option: ")

    if choice == "1":
        model_path = input("Enter model path: ")
        repo_name = model_version_control.create_repo()
        print(f"Repository created with name {repo_name}.")
    elif choice == "2":
        file_path = input("Enter file path: ")
        model_version_control.add_file(file_path)
        print(f"File {file_path} added to repository.")
    elif choice == "3":
        model_version_control.commit_changes()
        print("Changes committed to repository.")
    elif choice == "4":
        model_version_control.push_repo()
        print("Repository pushed to remote repository.")
    elif choice == "5":
        break
    else:
        print("Invalid option. Please choose again.")
