import os
import subprocess
import platform
import time

class MediaPlayer:
    def __init__(self):
        self.audio_files = []
        self.video_files = []

    def add_audio_file(self, file_path):
        self.audio_files.append(file_path)

    def add_video_file(self, file_path):
        self.video_files.append(file_path)

    def play(self):
        if not self.audio_files:
            print("No audio files found.")
            return
        if not self.video_files:
            print("No video files found.")
            return

        print("Select an audio file to play:")
        for i, file in enumerate(self.audio_files):
            print(f"{i+1}. {os.path.basename(file)}")

        while True:
            try:
                choice = int(input("Enter the number of your selected file: "))
                if 1 <= choice <= len(self.audio_files):
                    break
                else:
                    print("Invalid choice. Please try again.")
            except ValueError:
                print("Invalid input. Please enter a number.")

        audio_file = self.audio_files[choice - 1]
        print(f"Playing: {os.path.basename(audio_file)}")
        subprocess.run(["afplay", audio_file], check=True)

    def pause(self):
        print("Audio playback paused.")

    def stop(self):
        print("Audio playback stopped.")

    def seek(self, progress):
        print(f"Seeking to {progress}% of the file.")

    def play_video(self):
        print("Select a video file to play:")
        for i, file in enumerate(self.video_files):
            print(f"{i+1}. {os.path.basename(file)}")

        while True:
            try:
                choice = int(input("Enter the number of your selected file: "))
                if 1 <= choice <= len(self.video_files):
                    break
                else:
                    print("Invalid choice. Please try again.")
            except ValueError:
                print("Invalid input. Please enter a number.")

        video_file = self.video_files[choice - 1]
        print(f"Playing: {os.path.basename(video_file)}")
        subprocess.run(["avplay", video_file], check=True)

def main():
    media_player = MediaPlayer()

    while True:
        print("\nMedia Player Menu:")
        print("1. Play audio")
        print("2. Pause audio")
        print("3. Stop audio")
        print("4. Seek to a specific percentage")
        print("5. Play video")
        print("6. Quit")

        choice = input("Enter your choice: ")

        if choice == "1":
            media_player.play()
        elif choice == "2":
            media_player.pause()
        elif choice == "3":
            media_player.stop()
        elif choice == "4":
            media_player.seek(100)
        elif choice == "5":
            media_player.play_video()
        elif choice == "6":
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
```

This code defines a `MediaPlayer` class that provides a simple and intuitive interface for playing audio and video files on macOS. The class has methods for playing, pausing, stopping, and seeking to specific percentages of the files, as well as for playing and seeking video files. The `main` function provides a menu-driven interface for users to interact with the `MediaPlayer` class.

