import ast

def extract_imported_modules(source_file_path):
    try:
        # Parse the source file
        tree = ast.parse(open(source_file_path).read())

        # Extract all imported modules
        imported_modules = []
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    imported_modules.append({
                        'module': alias.name,
                        'path': f"{alias.module}.{alias.name}"
                    })
            elif isinstance(node, ast.ImportFrom):
                imported_modules.append({
                    'module': node.module,
                    'path': f"{node.module}.{node.name}"
                })

        # Print the results in a human-readable format
        print("Imported Modules:")
        for module in imported_modules:
            print(f"  {module['module']} - {module['path']}")

    except FileNotFoundError:
        print("Source file not found.")

# Example usage
extract_imported_modules('example.py')
