```python
from marshmallow import Schema, fields, ValidationError, ValidationErrorMessages

class UserSchema(Schema):
    username = fields.Str(required=True)
    email = fields.Email(required=True)
    password = fields.Str(required=True, hidden=True)

class ProductSchema(Schema):
    name = fields.Str(required=True)
    price = fields.Float(required=True)
    description = fields.Str(required=True)

def validate_user_data(user_data):
    try:
        UserSchema().load(user_data)
    except ValidationError as err:
        return err.messages

def validate_product_data(product_data):
    try:
        ProductSchema().load(product_data)
    except ValidationError as err:
        return err.messages

def main():
    user_data = {
        "username": "john_doe",
        "email": "john@example.com",
        "password": "123456"
    }

    print(validate_user_data(user_data))

    product_data = {
        "name": "Test Product",
        "price": 19.99,
        "description": "This is a test product."
    }

    print(validate_product_data(product_data))

if __name__ == "__main__":
    main()
```

This code defines two schemas, `UserSchema` and `ProductSchema`, to validate user and product data, respectively. It also defines two functions, `validate_user_data` and `validate_product_data`, to validate user and product data, respectively. The `main` function demonstrates how to use these functions to validate user and product data.

