import dns.resolver

class DnsProvider:
    """Base class for DNS providers."""
    def __init__(self, provider):
        self.provider = provider

    def query(self, host, type, answers):
        """Query the DNS provider for the specified host and type."""
        try:
            answers = dns.resolver.resolve(host, type, answers)
            return answers
        except dns.resolver.NoAnswer:
            print(f"No answer found for {host}")
            return None
        except dns.resolver.NXDOMAIN:
            print(f"Host {host} does not exist")
            return None
        except Exception as e:
            print(f"Error querying {host}: {str(e)}")
            return None

class GoogleDnsProvider(DnsProvider):
    """Google DNS provider implementation."""
    def __init__(self):
        super().__init__("8.8.8.8")

class AmazonDnsProvider(DnsProvider):
    """Amazon DNS provider implementation."""
    def __init__(self):
        super().__init__("9.109.111.111")

class MicrosoftDnsProvider(DnsProvider):
    """Microsoft DNS provider implementation."""
    def __init__(self):
        super().__init__("8.8.4.4")

def main():
    # Create a Google DNS provider
    provider = GoogleDnsProvider()

    # Query for A record for google.com
    answers = provider.query("google.com", "A")
    if answers:
        print(f"google.com (A) records:")
        for record in answers:
            print(record)

    # Query for NS records for google.com
    answers = provider.query("google.com", "NS")
    if answers:
        print(f"google.com (NS) records:")
        for record in answers:
            print(record)

    # Create an Amazon DNS provider
    provider = AmazonDnsProvider()

    # Query for A record for amazon.com
    answers = provider.query("amazon.com", "A")
    if answers:
        print(f"amazon.com (A) records:")
        for record in answers:
            print(record)

    # Query for MX records for amazon.com
    answers = provider.query("amazon.com", "MX")
    if answers:
        print(f"amazon.com (MX) records:")
        for record in answers:
            print(record)

    # Create a Microsoft DNS provider
    provider = MicrosoftDnsProvider()

    # Query for A record for microsoft.com
    answers = provider.query("microsoft.com", "A")
    if answers:
        print(f"microsoft.com (A) records:")
        for record in answers:
            print(record)

if __name__ == "__main__":
    main()
```

