import html5lib
from html5lib.htmlparser import HTMLParser

class HtmlParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.html = None
        self.ttypes = {}

    def handle_starttag(self, tag, attrs):
        if tag == 'html':
            self.html = True
        else:
            self.ttypes[tag] = self.ttypes.get(tag, [])
            self.ttypes[tag].append((tag, 'html5lib.html5lib.parser.HTML5Parser'))

    def handle_endtag(self, tag):
        if tag == 'html':
            self.html = False
        else:
            self.ttypes[tag] = self.ttypes.get(tag, [])

class Html5Parser:
    def __init__(self, html_string):
        self.parser = HtmlParser()
        self.parser.feed(html_string)
        self.ttypes = self.parser.ttypes

def parse_html(html_string):
    return Html5Parser(html_string)
