# Define a custom PDB-like object for the built-in Python debugger
class PdbLikeDebugger:
    def __init__(self):
        self.frame = None
        self.arguments = []
        self.locals = {}
        self.exit_code = None

    def __enter__(self):
        self.frame = inspect.currentframe().f_back
        self.frame.f_back = self
        self.frame.f_back.f_back = self
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.exit_code is not None:
