import yaml

class NestedYAMLConstructor(yaml.Constructors.SingleFileInstantiator):
    def _construct_yaml_node(self, node, parent, parent_type, parent_key, parent_value):
        if isinstance(parent_value, dict):
            for key, value in parent_value.items():
                if isinstance(value, dict):
                    self._construct_yaml_node(value, node, type(value), key, value)
                else:
                    node.append(value)
        elif isinstance(parent_value, list):
            for value in parent_value:
                if isinstance(value, dict):
                    self._construct_yaml_node(value, node, type(value), key, value)
                else:
                    node.append(value)
        else:
            node.append(parent_value)
