import paramiko

class PowerShellShell:
    def __init__(self, host, username, password, port=22, key_file='client_key.pem', cert_file='server_cert.pem'):
        self.host = host
        self.username = username
        self.password = password
        self.port = port
        self.key_file = key_file
        self.cert_file = cert_file

    def connect(self):
        try:
            ssh = paramiko.SSHClient()
            ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            ssh.connect(self.host, username=self.username, password=self.password, port=self.port)
            return ssh
        except Exception as e:
            print(f"Error connecting to {self.host}: {e}")
            return None

    def execute_command(self, command):
        try:
            ssh = self.connect()
            if ssh is None:
                return
            stdin, stdout, stderr = ssh.exec_command(command)
            output = stdout.read().decode()
            error = stderr.read().decode()
            if error:
                print(f"Error: {error}")
            else:
                print(f"Output: {output}")
            return stdout.read().decode()
        except Exception as e:
            print(f"Error executing command: {e}")
            return None

    def close(self):
        if self.connect():
            ssh.close()
            return

# Example usage
if __name__ == "__main__":
    host = "your_host_name"
    username = "your_username"
    password = "your_password"

    shell = PowerShellShell(host, username, password)
    command = "Get-Process -Name PowerShell"
    output = shell.execute_command(command)
    if output:
        print(output)
    shell.close()
```

