```python
# utility_module.py

def filter_data(data, predicate):
    """Returns a new iterable that includes only the elements for which the predicate function returns True"""
    for item in data:
        if predicate(item):
            yield item

def map_data(data, func):
    """Returns a new iterable that includes the results of applying the function to each item in the input data"""
    for item in data:
        yield func(item)

def reduce_data(data, func):
    """Returns the result of applying the function to the first two items in the input data, then to the third, and so on, until the input data is exhausted"""
    if len(data) == 0:
        return None
    accumulator = data[0]
    for item in data[1:]:
        accumulator = func(accumulator, item)
    return accumulator

def square_numbers(numbers):
    """Returns an iterable that includes the squares of each number in the input iterable"""
    for number in numbers:
        yield number ** 2

def sum_numbers(numbers):
    """Returns the sum of each number in the input iterable"""
    for number in numbers:
        yield number

def product_of_numbers(numbers):
    """Returns the product of each number in the input iterable"""
    for number in numbers:
        yield number
```

You can use these functions as follows:

```python
# Example usage
if __name__ == "__main__":
    numbers = [1, 2, 3, 4, 5]

    # Filter even numbers
    even_numbers = filter_data(numbers, lambda x: x % 2 == 0)
    print(list(even_numbers))  # Output: [2, 4]

    # Map square numbers
    squared_numbers = map_data(numbers, lambda x: x ** 2)
    print(list(squared_numbers))  # Output: [1, 4, 9, 16, 25]

    # Reduce sum
    sum_result = reduce_data(numbers, sum)
    print(sum_result)  # Output: 15

    # Product of numbers
    product_result = product_of_numbers(numbers)
    print(list(product_result))  # Output: 120
