# audit_log_app/models.py
from django.db import models
from django.contrib.auth.models import User
from django.utils import timezone

class Event(models.Model):
    user = models.ForeignKey(User, on_delete=models.CASCADE)
    event_type = models.CharField(max_length=100)
    description = models.TextField()
    created_at = models.DateTimeField(auto_now_add=True)

    def __str__(self):
        return f"{self.user.username} - {self.event_type}"

class AuditLog(models.Model):
    event = models.ForeignKey(Event, on_delete=models.CASCADE)
    timestamp = models.DateTimeField(auto_now_add=True)
    user = models.ForeignKey(User, on_delete=models.CASCADE)

    class Meta:
        verbose_name = "Audit Log"
        verbose_name_plural = "Audit Logs"
        ordering = ["-timestamp"]

# audit_log_app/views.py
from django.shortcuts import render, redirect
from django.contrib.auth.decorators import login_required
from .models import Event, AuditLog

def index(request):
    logs = AuditLog.objects.all()
    return render(request, "audit_log/index.html", {"logs": logs})

@login_required
def create_log(request):
    if request.method == "POST":
        event_type = request.POST.get("event_type")
        description = request.POST.get("description")
        user = request.user
        new_log = Event(user=user, event_type=event_type, description=description)
        new_log.save()
        return redirect("audit_log:index")
    return render(request, "audit_log/create_log.html")

@login_required
def log_view(request):
    logs = AuditLog.objects.all()
    return render(request, "audit_log/log_view.html", {"logs": logs})

@login_required
def filter_by_event_type(request):
    event_types = Event.objects.all()
    return render(request, "audit_log/filter_by_event_type.html", {"event_types": event_types})

@login_required
def filter_by_date_range(request):
    start_date = request.GET.get("start_date")
    end_date = request.GET.get("end_date")
    event_types = Event.objects.all()
    logs = AuditLog.objects.filter(event__event_type__in=event_types).filter(timestamp__gte=start_date, timestamp__le=end_date)
    return render(request, "audit_log/filter_by_date_range.html", {"event_types": event_types, "logs": logs})

@login_required
def user_log_view(request, pk):
    user = User.objects.get(pk=pk)
    logs = AuditLog.objects.filter(user=user)
    return render(request, "audit_log/user_log_view.html", {"logs": logs, "user": user})
```

