```python
import hashlib
import time
from typing import List

class Block:
    def __init__(self, index: int, previous_hash: str, timestamp: float, data: str, mining_hash: str, reward: float, penalty: float):
        self.index = index
        self.previous_hash = previous_hash
        self.timestamp = timestamp
        self.data = data
        self.mining_hash = mining_hash
        self.reward = reward
        self.penalty = penalty

    def solve_puzzle(self):
        # Implement Chia blockchain puzzle solving algorithm
        # For simplicity, we'll just return a random value
        return hashlib.sha256(str(time.time()).encode()).hexdigest()

class Blockchain:
    def __init__(self):
        self.chain = [self.create_genesis_block()]
        self.mining_hash = "0000000000000000000000000000000000000000"
        self.reward = 1.0
        self.penalty = 1.0

    def create_genesis_block(self) -> Block:
        return Block(0, self.mining_hash, time.time(), "Genesis Block", self.mining_hash, self.reward, self.penalty)

    def add_block(self, block: Block) -> None:
        block.previous_hash = self.chain[-1].mining_hash
        block.mining_hash = hashlib.sha256(str(block.timestamp).encode()).hexdigest()
        block.reward = block.reward / 2.0
        block.penalty = block.penalty / 2.0
        self.chain.append(block)

    def mine_block(self, block: Block) -> None:
        if block.timestamp > time.time() - 10:
            block.reward = block.reward * 2.0
            block.penalty = block.penalty * 2.0
            return
        block.solve_puzzle()

    def get_latest_block(self) -> Block:
        return self.chain[-1]

    def display_chain(self) -> None:
        for block in self.chain:
            print(f"Block {block.index} - Hash: {block.mining_hash}, Reward: {block.reward}, Penalty: {block.penalty}")


# Example usage
blockchain = Blockchain()

while True:
    blockchain.mine_block(blockchain.get_latest_block())
    blockchain.display_chain()
```

In this code, we define a `Block` class to represent individual blocks in the blockchain, and a `Blockchain` class to manage the entire chain. The `Blockchain` class includes methods for creating a genesis block, adding blocks to the chain, mining a block, and displaying the chain. The `mine_block` method solves a puzzle for the new block, and the `get_latest_block` method returns the latest block in the chain. The `display_chain` method prints out the details of each block in the chain. The example usage at the end creates a new blockchain, mines blocks, and displays the chain.

```python
from flask import Flask, request, jsonify
from boto3 import client

app = Flask(__name__)

def collect_profiling_data():
    """
    Collects profiling data from AWS services.
    """
    profiling_data = {
        'memory_usage': client.get_service_request('MemoryUsage', '2022-09-01').get('ResponseMetadata', {}).get('ContentLength'),
        'cpu_usage': client.get_service_request('CPUUsage', '2022-09-01').get('ResponseMetadata', {}).get('ContentLength'),
        'disk_usage': client.get_service_request('DiskUsage', '2022-09-01').get('ResponseMetadata', {}).get('ContentLength')
    }
    return profiling_data

def handle_profiling_request():
    """
    Handles incoming profiling requests from Amazon CodeGuru Profiler.
    """
    profiling_data = collect_profiling_data()
    if profiling_data:
        return jsonify(profiling_data)
    else:
        return jsonify({'error': 'No profiling data available'}), 500

@app.route('/profiling', methods=['POST'])
def handle_profiling_request_request():
    """
    Handles incoming profiling requests from Amazon CodeGuru Profiler.
    """
    data = request.get_json()
    if 'profiling_data' in data:
        return handle_profiling_request()
    else:
        return jsonify({'error': 'Missing profiling data'}), 400

if __name__ == '__main__':
    app.run(debug=True)
```

