import inspect

class Debugger:
    def __init__(self, code):
        self.code = code
        self.lines = code.split('\n')
        self.current_line = 0
        self.breakpoint = None
        self.set_breakpoint()

    def set_breakpoint(self, line, condition):
        for i, line_num in enumerate(self.lines):
            if line_num == line:
                self.breakpoint = (i, line_num)
                break
        else:
            raise ValueError("Invalid line number")

    def step(self):
        if self.breakpoint:
            line_num, line_value = self.breakpoint
            self.current_line = line_num
            print(f"Current line: {self.lines[self.current_line]}")
            print(f"Value of variable at current line: {self.get_variable_value(line_num)}")
        else:
            self.current_line += 1
            print(f"Current line: {self.lines[self.current_line]}")

    def get_variable_value(self, line_num):
        line_value = None
        for i, line_num in enumerate(self.lines):
            if line_num == line_num:
                line_value = self.lines[i].split('=')[1].strip()
                break
        return line_value

def main():
    code = """
def add(a, b):
    return a + b

print(add(2, 3))

x = 5
y = 10
print(x + y)
"""

    debugger = Debugger(code)
    while True:
        debugger.step()
        cont = input("Do you want to step again? (yes/no): ")
        if cont.lower() != "yes":
            break

if __name__ == "__main__":
    main()
```

