import os
from PyPDF2 import PdfFileReader, PdfFileWriter

def read_pdf(file_path):
    """Reads a PDF file and returns its contents."""
    try:
        pdf_file_obj = open(file_path, 'rb')
        pdf_reader = PdfFileReader(pdf_file_obj)
        num_pages = pdf_reader.numPages
        print(f"PDF file has {num_pages} pages.")
        return pdf_reader.pages[0].extractText()
    except FileNotFoundError:
        print("The file was not found.")
        return None
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def write_pdf(file_path, content):
    """Writes content to a PDF file."""
    try:
        pdf_file_obj = open(file_path, 'wb')
        pdf_writer = PdfFileWriter()
        pdf_writer.addPage(PdfFileReader(pdf_file_obj)..getPage(0).extractText())
        pdf_writer.addPage(PdfFileReader(open(content, 'rb')).getPage(0).extractText())
        pdf_writer.write(open(file_path, 'wb'))
    except Exception as e:
        print(f"An error occurred: {e}")

def extract_text(file_path):
    """Extracts text from a PDF file."""
    try:
        return read_pdf(file_path)
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def layout_extract(file_path):
    """Extracts layout information from a PDF file."""
    try:
        return read_pdf(file_path)
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def create_pdf(file_path, content):
    """Creates a new PDF document with the given content."""
    try:
        write_pdf(file_path, content)
    except Exception as e:
        print(f"An error occurred: {e}")

def modify_pdf(file_path, content):
    """Modifies an existing PDF file with the given content."""
    try:
        write_pdf(file_path, content)
    except Exception as e:
        print(f"An error occurred: {e}")

# Example usage:
content = extract_text("example.pdf")
layout = layout_extract("example.pdf")
create_pdf("example.pdf", content)
modify_pdf("example.pdf", "Modified content")
```

