import openmetadata
from openmetadata.metadata import Metadata
from openmetadata.search import Search
from openmetadata.update import Update
from openmetadata.delete import Delete

class IngestionFramework:
    def __init__(self):
        self.metadata = {}

    def create_metadata(self, metadata_id, metadata_name, metadata_description):
        """Create a new metadata object and add it to the ingestion framework."""
        self.metadata[metadata_id] = Metadata(
            metadata_name=metadata_name,
            metadata_description=metadata_description
        )
        self.update_metadata(metadata_id, metadata_name, metadata_description)

    def update_metadata(self, metadata_id, metadata_name=None, metadata_description=None):
        """Update an existing metadata object."""
        if metadata_id in self.metadata:
            if metadata_name:
                self.metadata[metadata_id].metadata_name = metadata_name
            if metadata_description:
                self.metadata[metadata_id].metadata_description = metadata_description
        else:
            print("Metadata not found.")

    def delete_metadata(self, metadata_id):
        """Delete a metadata object."""
        if metadata_id in self.metadata:
            del self.metadata[metadata_id]
        else:
            print("Metadata not found.")

    def query_metadata(self, search_criteria):
        """Query metadata objects based on a search criteria."""
        search = Search()
        search_criteria = self.convert_search_criteria(search_criteria)
        results = search.search(search_criteria)
        return results

    def convert_search_criteria(self, search_criteria):
        """Convert search criteria to a format that can be used by the search function."""
        # Convert search criteria to a dictionary
        criteria_dict = {}
        if 'term' in search_criteria:
            criteria_dict['term'] = search_criteria['term']
        if 'range' in search_criteria:
            criteria_dict['range'] = search_criteria['range']
        if 'contains' in search_criteria:
            criteria_dict['contains'] = search_criteria['contains']
        return criteria_dict

    def update_metadata_id(self, metadata_id, metadata_name, metadata_description):
        """Update the metadata object with the given ID."""
        if metadata_id in self.metadata:
            self.metadata[metadata_id].metadata_name = metadata_name
            self.metadata[metadata_id].metadata_description = metadata_description
        else:
            print("Metadata not found.")

    def delete_metadata_id(self, metadata_id):
        """Delete the metadata object with the given ID."""
        if metadata_id in self.metadata:
            del self.metadata[metadata_id]
        else:
            print("Metadata not found.")

# Example usage:
ingestion_framework = IngestionFramework()

# Create metadata
ingestion_framework.create_metadata(
    1,
    "Example Metadata",
    "This is an example metadata object."
)

# Update metadata
ingestion_framework.update_metadata(
    1,
    metadata_name="Updated Metadata"
)

# Delete metadata
ingestion_framework.delete_metadata(1)

# Query metadata
results = ingestion_framework.query_metadata(
    search_criteria={"term": "Example Metadata"}
)

# Update metadata ID
ingestion_framework.update_metadata_id(
    1,
    metadata_name="Updated Metadata",
    metadata_description="This is an updated metadata object."
)

# Delete metadata ID
ingestion_framework.delete_metadata_id(1)
