    # Define the declension rules for each noun
    declensions = {
        'neut': ['záměna', 'čestěna', 'pochastěna'],
        'masc': ['pán', 'paní', 'pan', 'pání', 'paní', 'paní', 'paní', 'pání', 'paní'],
        'fem': ['dám', 'dám', 'dám', 'dám', 'dám', 'dám', 'dám', 'dám', 'dám'],
        'neut plne': ['záměna', 'čestěna', 'pochastěna'],
        'neut mlece': ['záměna', 'čestěna', 'pochastěna'],
        'neut plne mlece': ['záměna', 'čestěna', 'pochastěna'],
        'neut mlec': ['záměna', 'čestěna', 'pochastěna'],
        'neut mlec mlece': ['záměna', 'čestěna', 'pochastěna'],
        'fem plne': ['dám', 'dám', 'dám', 'dám', 'dám', 'dám', 'dám', 'dám', 'dám'],
        'fem mlece': ['dám', 'dám', 'dám', 'dám', 'dám', 'dám', 'dám', 'dám', 'dám'],
        'fem mlec': ['dám', 'dám', 'dám', 'dám', 'dám', 'dám', 'dám', 'dám', 'dám'],
        'fem mlec mlece': ['dám', 'dám', 'dám', 'dám', 'dám', 'dám', 'dám', 'dám', 'dám'],
    }

    # Check if the input is a Czech name
    if not czech_name[0].isalpha() or not czech_name[-1].isalpha():
        return None

    # Get the first letter of the input name
    first_letter = czech_name[0]

    # Get the last letter of the input name
    last_letter = czech_name[-1]

    # Check if the input name is a noun
    if first_letter not in declensions['neut'] and first_letter not in declensions['masc']:
        return None

    # Check if the input name is a neuter noun
    if first_letter in declensions['neut'] and first_letter not in declensions['masc']:
        # Check if the last letter is a vowel
        if last_letter.lower() in 'aeiou':
            # Get the declension of the noun
