            elif last_letter.lower() == 'e':
                declension_type += 'n'
            elif last_letter.lower() == 'a':
                declension_type += 'a'
            elif last_letter.lower() == 'o':
                declension_type += 'e'
            return declension_type + ' ' + czech_name[1:]
        else:
            # Get the declension of the noun
