from dagster import PipelineDefinition, run, DagsterException

# Define a pipeline that executes a Docker container as a step
def create_docker_pipeline():
    """
    Create a pipeline that executes a Docker container as a step.

    This pipeline will create a new container, run a command inside the container, 
    and then remove the container.
    """

    # Define the pipeline definition
    pipeline = PipelineDefinition(
        name="Docker Pipeline",
        stages=[
            {
                "task": "docker_container",
                "config": {
                    "image": "my-image",
                    "command": ["run", "-it", "-v", "/var/lib/dagster", "my-app"],
                    "env": {
                        "MY_VAR": "my_value"
                    },
                    "docker": {
                        "image": "my-image"
                    }
                }
            },
            {
                "task": "remove_container",
                "config": {
                    "image": "my-image"
                }
            }
        ]
    )

    try:
        # Run the pipeline
        run(pipeline)
    except DagsterException as e:
        # Handle any errors that occur during pipeline execution
        print(f"Error: {e}")
