1. Hash Table for Strings
```python
import hashlib

class StringHashTable:
    def __init__(self):
        self.table = [[] for _ in range(100)]

    def _hash(self, string):
        return hashlib.sha256(string.encode()).hexdigest()[:8]

    def insert(self, string, value):
        hash_value = self._hash(string)
        for pair in self.table[hash_value]:
            if pair[0] == string:
                pair[1] = value
                break
        else:
            self.table[hash_value].append([string, value])

    def get(self, string):
        hash_value = self._hash(string)
        for pair in self.table[hash_value]:
            if pair[0] == string:
                return pair[1]
        return None

    def delete(self, string):
        hash_value = self._hash(string)
        for i, pair in enumerate(self.table[hash_value]):
            if pair[0] == string:
                del self.table[hash_value][i]
                return

# Example usage:
hash_table = StringHashTable()
hash_table.insert("apple", 5)
hash_table.insert("banana", 10)
print(hash_table.get("apple"))  # Output: 5
hash_table.delete("banana")
print(hash_table.get("banana"))  # Output: None
