import json
import os

class USDSceneDescription:
    def __init__(self, name, description, scene_graph):
        self.name = name
        self.description = description
        self.scene_graph = scene_graph

    @classmethod
    def from_dict(cls, data):
        return cls(
            name=data.get('name', ''),
            description=data.get('description', ''),
            scene_graph=data.get('scene_graph', {})
        )

    @classmethod
    def from_file(cls, filename):
        with open(filename, 'r') as f:
            data = json.load(f)
        return cls(
            name=data.get('name'),
            description=data.get('description'),
            scene_graph=data.get('scene_graph', {})
        )

    def export_to_usd(self):
        usd_data = {
            'scenes': [
                {
                    'name': self.name,
                    'description': self.description,
                    'scene_graph': self.scene_graph
                }
            ]
        }
        return usd_data

    def export_to_file(self, filename):
        usd_data = self.export_to_usd()
        with open(filename, 'w') as f:
            json.dump(usd_data, f, indent=4)

    def export_to_ply(self):
        ply_data = {
            'vertices': [],
            'faces': []
        }
        for object in self.scene_graph.get('objects', []):
            vertices = []
            for material in object.get('materials', []):
                for face in material.get('faces', []):
                    vertices.extend(face.get('vertices', []))
            ply_data['vertices'] += vertices
            ply_data['faces'] += face.get('faces', [])
        with open('output.ply', 'w') as f:
            f.write('\n'.join(['v %s %s %s' % (x, y, z) for x, y, z in ply_data['vertices']] + [
                'f %s %s %s' % (a, b, c)
                for a, b, c in ply_data['faces']
            ]))
