```python
class GeneratorChainer:
    def __init__(self):
        self.gen = None

    def __iter__(self):
        return self.gen

    def __next__(self):
        if self.gen is None:
            self.gen = (next for next in self.gen)
        return self.gen.__next__()

    def __bool__(self):
        return bool(self.gen)

    def chain(self, *iterables):
        gen = (iterable for iterable in iterables)
        return GeneratorChainer(gen)

    def filter(self, predicate):
        return GeneratorChainer((gen for gen in self.gen if predicate(gen)))

    def map(self, func):
        return GeneratorChainer((gen for gen in self.gen if func(gen)))

    def reduce(self, func, init):
        return GeneratorChainer((gen for gen in self.gen if func(gen) == init))

    def all(self):
        return all(self.gen)


# Example usage
if __name__ == "__main__":
    gen = GeneratorChainer()
    gen = gen.chain(range(10), range(5))
    gen = gen.filter(lambda x: x % 2 == 0)
    gen = gen.map(lambda x: x * 2)
    gen = gen.reduce(lambda x, y: x + y, 0)
    print(gen.all())
```

