import boto3
from botocore.exceptions import ClientError

class S3Interface:
    def __init__(self, access_key, secret_key, bucket_name):
        self.s3 = boto3.client('s3', 
                              aws_access_key_id=access_key, 
                              aws_secret_access_key=secret_key, 
                              region_name='us-east-1')

    def list_objects(self, bucket_name, prefix=None):
        try:
            response = self.s3.list_objects_v2(Bucket=bucket_name, Prefix=prefix)
            return response.get('Contents', [])
        except ClientError as e:
            print(f"An error occurred: {e}")

    def create_bucket(self, bucket_name):
        try:
            self.s3.create_bucket(Bucket=bucket_name)
            return f"Bucket {bucket_name} created successfully"
        except ClientError as e:
            return f"Error creating bucket: {e}"

    def upload_file(self, bucket_name, file_name, file_content):
        try:
            self.s3.upload_file(file_name, bucket_name, file_content)
            return f"File uploaded successfully to {bucket_name}"
        except ClientError as e:
            return f"Error uploading file: {e}"

    def download_file(self, bucket_name, file_name):
        try:
            response = self.s3.get_object(Bucket=bucket_name, Key=file_name)
            return response.get('Body').read()
        except ClientError as e:
            return f"Error downloading file: {e}"

# Usage example
interface = S3Interface('YOUR_ACCESS_KEY', 'YOUR_SECRET_KEY', 'YOUR_BUCKET_NAME')
print(interface.create_bucket('my-new-bucket'))
print(interface.list_objects('my-new-bucket'))
print(interface.upload_file('my-new-bucket', 'test.txt', 'Hello, World!'))
print(interface.download_file('my-new-bucket', 'test.txt'))
