import har
from collections import defaultdict

class HARParser:
    def __init__(self, file_path):
        self.file_path = file_path
        self.har_data = har.ParsedHTTPResponse(file_path)

    def extract_requests(self):
        requests = defaultdict(list)
        for record in self.har_data.records:
            if record.http_version == 'HTTP/1.1':
                requests[record.url].append({
                    'method': record.request_method,
                    'status_code': record.status_code,
                    'headers': record.headers,
                    'body_length': len(record.body)
                })
        return requests

    def extract_responses(self):
        responses = defaultdict(list)
        for record in self.har_data.records:
            if record.http_version == 'HTTP/1.1':
                responses[record.url].append({
                    'method': record.request_method,
                    'status_code': record.status_code,
                    'headers': record.headers,
                    'body_length': len(record.body)
                })
        return responses

    def extract_performance_metrics(self):
        performance_metrics = defaultdict(list)
        for record in self.har_data.records:
            if record.http_version == 'HTTP/1.1':
                metrics = {
                    'request_time': record.request_time,
                    'response_time': record.response_time,
                    'throughput': record throughput
                }
                performance_metrics[record.url].append(metrics)
        return performance_metrics

    def extract_data(self):
        requests_data = {}
        responses_data = {}
        performance_metrics_data = {}
        for url, metrics in self.extract_performance_metrics().items():
            for metric, value in metrics.items():
                if metric in ['request_time', 'response_time']:
                    requests_data[url] = value
                elif metric in ['throughput']:
                    performance_metrics_data[url] = value
                else:
                    responses_data[url] = value
        return requests_data, responses_data, performance_metrics_data

# Example usage
parser = HARParser('path_to_your_har_file.har')
requests_data, responses_data, performance_metrics_data = parser.extract_data()
print("Requests Data:")
for url, metrics in requests_data.items():
    print(f"URL: {url}")
    for metric, value in metrics.items():
        print(f"  {metric}: {value}")
print("\nResponses Data:")
for url, metrics in responses_data.items():
    print(f"URL: {url}")
    for metric, value in metrics.items():
        print(f"  {metric}: {value}")
print("\nPerformance Metrics Data:")
for url, metrics in performance_metrics_data.items():
    print(f"URL: {url}")
    for metric, value in metrics.items():
        print(f"  {metric}: {value}")
