# Import necessary modules
import collections

# Create a subclass for lists
class List:
    def __init__(self, elements):
        self.elements = elements

    def __repr__(self):
        return f"List({self.elements})"

    def append(self, element):
        self.elements.append(element)

    def sort(self):
        self.elements.sort()

    def search(self, target):
        return self.elements.index(target)

    def __len__(self):
        return len(self.elements)

# Create a subclass for dictionaries
class Dict:
    def __init__(self, data):
        self.data = data

    def __repr__(self):
        return f"Dict({self.data})"

    def get(self, key, default=None):
        return self.data.get(key, default)

    def set(self, key, value):
        self.data[key] = value

    def __len__(self):
        return len(self.data)

# Create a subclass for strings
class String:
    def __init__(self, value):
        self.value = value

    def __repr__(self):
        return f"String({self.value})"

    def append(self, value):
        self.value += value

    def search(self, target):
        return self.value.find(target)

    def __len__(self):
        return len(self.value)

# Create a subclass for sets
class Set:
    def __init__(self, elements):
        self.elements = set(elements)

    def __repr__(self):
        return f"Set({self.elements})"

    def add(self, element):
        self.elements.add(element)

    def remove(self, element):
        self.elements.discard(element)

    def __len__(self):
        return len(self.elements)

# Create a subclass for tuples
class Tuple:
    def __init__(self, elements):
        self.elements = elements

    def __repr__(self):
        return f"Tuple({self.elements})"

    def append(self, element):
        self.elements.append(element)

    def search(self, target):
        return self.elements.index(target)

    def __len__(self):
        return len(self.elements)

# Create a subclass for frozensets
class Frozenset:
    def __init__(self, elements):
        self.elements = frozenset(elements)

    def __repr__(self):
        return f"Frozenset({self.elements})"

    def add(self, element):
        self.elements.add(element)

    def remove(self, element):
        self.elements.remove(element)

    def __len__(self):
        return len(self.elements)
