import py2exe

class TrayIconApp:
    def __init__(self):
        self.main_window = None
        self.tray_icon_path = None
        self.minimized = False

    def run(self):
        # Create a main window
        self.main_window = py2exe.create_window(title="My App",
                                             width=400,
                                             height=200,
                                             icon=self.tray_icon_path)

        # Create a system tray icon
        self.tray_icon = py2exe.create_icon("system_tray_icon.ico", size=(16, 16), icon=self.tray_icon_path)

        # Add an event handler for the system tray icon
        def on_tray_click():
            if not self.minimized:
                self.main_window.minimize()
                self.minimized = True
            else:
                self.main_window.restore()

        # Add the event handler to the system tray icon
        self.tray_icon.on_tray_click(on_tray_click)

        # Start the py2exe executable
        py2exe.startsetup({
            "console": {
                "script": "main.py"
            }
        })

if __name__ == "__main__":
    app = TrayIconApp()
    app.run()
