import markdown
from markdown.extensions import TableExtension

class SanityListTableExtension(TableExtension):
    def __init__(self, parser):
        self.parser = parser
        super().__init__(parser, 'table', None, None, None, None, None, None, None)

    def handle_starttag(self, tag, name, attrs):
        if name == 'li':
            self.parser.add_block_list()

    def handle_endtag(self, tag, name):
        if name == 'li':
            self.parser.remove_block_list()

    def handle_data(self, data):
        if data.strip() and data[-1] == '\n':
            self.parser.add_linebreak(data)

def markdownify(text):
    return markdown.markdown(text, extensions=[SanityListTableExtension])

# Example usage:
print(markdownify('This is a list\n  * item 1\n  * item 2\n'))
